import {plans,money,findService} from './catalog.mjs';
export function homeMarkup({root='./'}={}){
 const src=n=>root+'assets/'+n;
 const quote=(id,vehicle='car')=>root+'atendimento/?vehicle='+vehicle+'&service='+id;
 const photo=(name,alt,pos='50% 50%')=>'<img src="'+src(name)+'" alt="'+alt+'" style="object-position:'+pos+'" width="900" height="700" loading="lazy" decoding="async">';
 const tiles=[['essential','Lavagem','modern-gt3.webp','50% 62%','A partir de'],['fullClean','Higienização','modern-interior.webp','53% 50%',''],['polishLight','Polimento','detail-finish.webp','50% 65%','A partir de'],['coating','Vitrificação','modern-mclaren.webp','45% 51%','']];
 return `<section class="fn-hero" aria-labelledby="hero-title"><div class="fn-hero-heading"><div><h1 id="hero-title">Seu veículo.<br>Em boa forma.</h1><p>Estética para carros e motos.</p></div><span class="fn-hero-sign">FINE FORM<br><b>CAR CARE</b></span></div><div class="fn-showroom"><div class="fn-car-host" data-home-car><img class="fn-car-fallback" src="${src('car-preview.webp')}" alt="Cupê prateado em vista frontal e lateral" width="800" height="500" fetchpriority="high" decoding="async"></div><div class="fn-showroom-controls" role="group" aria-label="Ver o carro"><button type="button" data-home-focus="geral" aria-pressed="true">Exterior</button><button type="button" data-home-focus="interior" aria-pressed="false">Interior</button><button type="button" data-home-focus="rodas" aria-pressed="false">Rodas</button></div><span class="fn-drag-note">Arraste para girar</span></div><div class="fn-hero-actions"><a class="fn-button fn-black" href="${quote('premium')}">Escolher cuidado <span aria-hidden="true">↗</span></a><a class="fn-text-link" href="#care">Conhecer o Care <span aria-hidden="true">↓</span></a></div></section>
 <section class="fn-care" id="care" aria-labelledby="care-title"><div class="fn-care-banner"><div class="fn-care-banner-copy"><span class="fn-care-brand">FINE FORM <b>CARE</b></span><h2 id="care-title">Bom cuidado.<br>Todo mês.</h2><p>Seu plano de cuidado mensal.</p><a class="fn-button fn-white" href="${root}atendimento/?mode=plan&plan=careEssential">Escolher plano <span aria-hidden="true">↗</span></a></div><div class="fn-care-banner-photo">${photo('detail-finish.webp','Pintura vermelha com acabamento brilhante e uma toalha de microfibra','50% 42%')}</div></div><div class="fn-plan-grid">${plans.map(p=>`<a class="fn-plan ${p.id==='careFrequent'?'fn-plan-featured':''} ${p.vehicle==='moto'?'fn-plan-moto':''}" href="${root}atendimento/?mode=plan&vehicle=${p.vehicle}&plan=${p.id}"><div class="fn-plan-name"><h3>${p.name.replace('Care ','')}</h3><span aria-hidden="true">↗</span></div><p class="fn-plan-visits">${p.visits} ${p.vehicle==='moto'?'lavagens':'visitas'} / mês</p><p class="fn-plan-price">${money(p.price)}<small>/mês</small></p><p class="fn-plan-desc">${p.description.replace('Uma Premium + uma Essencial','1 Premium + 1 Essencial').replace('Uma Premium + três Essenciais','1 Premium + 3 Essenciais').replace('Duas lavagens Moto Premium','2 lavagens Moto Premium').replace(' por mês.','')}</p><span class="fn-plan-saving">Economize ${money(p.saving)} por mês</span></a>`).join('')}</div><p class="fn-plan-note">Planos para um único veículo. Visitas com horário combinado.</p></section>
 <section class="fn-services" id="cuidados" aria-labelledby="services-title"><div class="fn-section-heading"><h2 id="services-title">Seu próximo cuidado.</h2><a class="fn-text-link" href="${root}atendimento/">Ver todos <span aria-hidden="true">↗</span></a></div><div class="fn-service-grid">${tiles.map(([id,title,image,pos,prefix])=>{const s=findService(id);return `<a class="fn-service" href="${quote(id)}"><div class="fn-service-photo">${photo(image,title,pos)}<span aria-hidden="true">↗</span></div><h3>${title}</h3><p>${prefix?prefix+' ':''}<b>${money(s.price)}</b></p></a>`}).join('')}</div><a class="fn-moto-link" href="${quote('motoPremium','moto')}">${photo('modern-ducati.webp','Moto Ducati Panigale')}<span><b>Seu cuidado em duas rodas.</b><small>Moto Premium · ${money(findService('motoPremium').price)}</small></span><span aria-hidden="true">↗</span></a></section>
 <section class="fn-reviews" id="avaliacoes" aria-labelledby="reviews-title"><div class="fn-section-heading"><h2 id="reviews-title">Quem já passou por aqui.</h2></div><p id="reviews-summary">Avaliações dos nossos clientes.</p><div class="reviews-list" id="reviews-list" aria-live="polite"></div><button class="fn-button fn-black" id="reviews-more" type="button" hidden>Ver mais avaliações</button></section>
 <section class="fn-personal" id="sobre" aria-labelledby="personal-title"><div><span class="fn-care-brand">PRAZER, MATEUS.</span><h2 id="personal-title">Seu carro.<br>Minha atenção.</h2></div><div><p>Você fala comigo, escolhe o cuidado e combina os detalhes antes de começar. Um veículo por vez.</p><button type="button" class="fn-button fn-black" data-contact>Vamos conversar <span aria-hidden="true">↗</span></button></div></section>`;
}
